import 'package:mad_flutter_practicum/domain/domain.dart';

class DashboardPage extends StatefulWidget {
  const DashboardPage({super.key});

  @override
  State<DashboardPage> createState() => _DashboardPageState();
}

class _DashboardPageState extends State<DashboardPage> {
  late Future<Map<String, dynamic>> _dashboardFuture;

  @override
  void initState() {
    super.initState();
    _initData();
  }

  void _initData() {
    final currencyRepository = context.read<CurrencyRepository>();
    final newsRepository = context.read<NewsRepository>();

    final fetchRates = currencyRepository.fetchRates(
      const CurrencyPageRequest(base: 'USD'),
    );

    final loadFeed = newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true));

    _dashboardFuture = Future.wait([fetchRates, loadFeed]).then((List<Future> results) {
      return {
        'rates': results[0] as CurrencyPage,
        'news': results[1] as List<NewsModel>,
      };
    });
  }

  @override
  Widget build(BuildContext context) {
    final AppLocalizations loc = context.loc;

    return Scaffold(
      appBar: AppBar(title: Text(loc.dashboardTitle)),
      body: FutureBuilder<Map<String, dynamic>>(
        future: _dashboardFuture,
        builder: (BuildContext context, AsyncSnapshot<Map<String, dynamic>> snapshot) {
          if (!snapshot.hasData) {
            return const Center(child: CircularProgressIndicator());
          }

          final CurrencyPage rates = snapshot.data!['rates'] as CurrencyPage;
          final List<NewsModel> news = snapshot.data!['news'] as List<NewsModel>;

          return ListView(
            padding: const EdgeInsets.all(16),
            children: [
              // Currency section header
              Padding(
                padding: const EdgeInsets.only(bottom: 8),
                child: Text(
                  loc.currencyRate,
                  style: context.fonts.semiBold14,
                ),
              ),

              // Top currencies list
              ...rates.items.take(5).map((currency) => Padding(
                    padding: const EdgeInsets.only(bottom: 8),
                    child: CurrencyCard(model: currency),
                  )),

              // News section header
              Padding(
                padding: const EdgeInsets.only(top: 16, bottom: 8),
                child: Text(
                  loc.news,
                  style: context.fonts.semiBold14,
                ),
              ),

              ...news.take(5).map((newsItem) => Padding(
                    padding: const EdgeInsets.only(bottom: 8),
                    child: NewsCard(model: newsItem),
                  )),
            ],
          );
        },
      ),
    );
  }
}
